INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('clean-white', 'クリーンホワイト', '汎用的でシンプルな白ベースのテーマ', true, true, '{"cssContent":"/* クリーンホワイト - 汎用的でシンプルな白ベースのテーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #FFFFFF;\n  --theme-text-color: #1F2937;\n  --theme-border-color: #E5E7EB;\n  --theme-hover-bg-color: #F9FAFB;\n  --theme-accent-color: #3B82F6;\n  --theme-heading-color: #111827;\n  --theme-subtext-color: #6B7280;\n  --theme-muted-text-color: #9CA3AF;\n  --theme-divider-color: #F3F4F6;\n\n  /* Typography */\n  --theme-font-family: \"Inter\", system-ui, sans-serif;\n  --theme-font-size: 1rem;\n  --theme-heading-font-size: 1.5rem;\n  --theme-small-font-size: 0.875rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 600;\n  --theme-bold-font-weight: 700;\n  --theme-line-height: 1.6;\n\n  /* Layout */\n  --theme-padding: 1rem;\n  --theme-margin: 0.5rem;\n  --theme-border-radius: 0.5rem;\n  --theme-border-width: 1px;\n  --theme-box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.1);\n\n  /* Animations */\n  --theme-transition-duration: 200ms;\n  --theme-hover-transition: all 200ms ease-in-out;\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  transition: var(--theme-hover-transition);\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n}","version":"1.0","type":"css-based","accessibility":null}', NOW(), NOW(), NULL);
INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('soft-gray', 'ソフトグレー', '目に優しいグレーベースのテーマ', true, true, '{"cssContent":"/* ソフトグレー - 目に優しいグレーベースのテーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #F8F9FA;\n  --theme-text-color: #374151;\n  --theme-border-color: #D1D5DB;\n  --theme-hover-bg-color: #F3F4F6;\n  --theme-accent-color: #6366F1;\n  --theme-heading-color: #1F2937;\n  --theme-subtext-color: #6B7280;\n  --theme-muted-text-color: #9CA3AF;\n  --theme-divider-color: #E5E7EB;\n\n  /* Typography */\n  --theme-font-family: system-ui, -apple-system, sans-serif;\n  --theme-font-size: 1rem;\n  --theme-heading-font-size: 1.5rem;\n  --theme-small-font-size: 0.875rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 600;\n  --theme-line-height: 1.6;\n\n  /* Layout */\n  --theme-padding: 1rem;\n  --theme-margin: 0.5rem;\n  --theme-border-radius: 0.375rem;\n  --theme-border-width: 1px;\n  --theme-box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);\n\n  /* Animations */\n  --theme-transition-duration: 150ms;\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  transition: background-color var(--theme-transition-duration);\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n}","version":"1.0","type":"css-based","accessibility":null}', NOW(), NOW(), NULL);
INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('dark-mode', 'ダークモード', '夜間作業に適したダークテーマ', true, true, '{"cssContent":"/* ダークモード - 夜間作業に適したダークテーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #1F2937;\n  --theme-text-color: #F9FAFB;\n  --theme-border-color: #374151;\n  --theme-hover-bg-color: #374151;\n  --theme-accent-color: #60A5FA;\n  --theme-heading-color: #FFFFFF;\n  --theme-subtext-color: #D1D5DB;\n  --theme-muted-text-color: #9CA3AF;\n  --theme-divider-color: #4B5563;\n\n  /* Typography */\n  --theme-font-family: \"Inter\", system-ui, sans-serif;\n  --theme-font-size: 1rem;\n  --theme-heading-font-size: 1.5rem;\n  --theme-small-font-size: 0.875rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 600;\n  --theme-line-height: 1.6;\n\n  /* Layout */\n  --theme-padding: 1rem;\n  --theme-margin: 0.5rem;\n  --theme-border-radius: 0.5rem;\n  --theme-border-width: 1px;\n  --theme-box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3);\n\n  /* Animations */\n  --theme-transition-duration: 200ms;\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  transition: background-color var(--theme-transition-duration);\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n}","version":"1.0","type":"css-based","accessibility":null}', NOW(), NOW(), NULL);
INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('professional', 'プロフェッショナル', 'ビジネス文書に適した洗練されたテーマ', true, true, '{"cssContent":"/* プロフェッショナル - ビジネス文書に適した洗練されたテーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #FAFAFA;\n  --theme-text-color: #2D3748;\n  --theme-border-color: #CBD5E0;\n  --theme-hover-bg-color: #F7FAFC;\n  --theme-accent-color: #2B6CB0;\n  --theme-heading-color: #1A202C;\n  --theme-subtext-color: #4A5568;\n  --theme-muted-text-color: #718096;\n  --theme-divider-color: #E2E8F0;\n\n  /* Typography */\n  --theme-font-family: \"Roboto\", \"Helvetica Neue\", sans-serif;\n  --theme-font-size: 1rem;\n  --theme-heading-font-size: 1.5rem;\n  --theme-small-font-size: 0.875rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 500;\n  --theme-line-height: 1.7;\n\n  /* Layout */\n  --theme-padding: 1.25rem;\n  --theme-margin: 0.75rem;\n  --theme-border-radius: 0.25rem;\n  --theme-border-width: 1px;\n  --theme-box-shadow: 0 2px 4px 0 rgba(0, 0, 0, 0.06);\n\n  /* Animations */\n  --theme-transition-duration: 150ms;\n\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  transition: background-color var(--theme-transition-duration);\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n}","version":"1.0","type":"css-based","accessibility":null}', NOW(), NOW(), NULL);
INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('executive', 'エグゼクティブ', '重要な文書に適した格調高いテーマ', true, true, '{"cssContent":"/* エグゼクティブ - 重要な文書に適した格調高いテーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #F7F8FC;\n  --theme-text-color: #1A202C;\n  --theme-border-color: #D4AF37;\n  --theme-hover-bg-color: #F1F5F9;\n  --theme-accent-color: #744210;\n  --theme-heading-color: #2D3748;\n  --theme-subtext-color: #4A5568;\n  --theme-muted-text-color: #718096;\n  --theme-divider-color: #E2E8F0;\n\n  /* Typography */\n  --theme-font-family: \"Crimson Text\", \"Times New Roman\", serif;\n  --theme-font-size: 1.125rem;\n  --theme-heading-font-size: 1.75rem;\n  --theme-small-font-size: 1rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 600;\n  --theme-line-height: 1.8;\n\n  /* Layout */\n  --theme-padding: 1.5rem;\n  --theme-margin: 1rem;\n  --theme-border-radius: 0.125rem;\n  --theme-border-width: 2px;\n  --theme-box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);\n\n  /* Animations */\n  --theme-transition-duration: 250ms;\n\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  transition: background-color var(--theme-transition-duration);\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n}","version":"1.0","type":"css-based","accessibility":null}', NOW(), NOW(), NULL);
INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('study-blue', 'スタディブルー', '集中力を高める青ベースの学習テーマ', true, true, '{"cssContent":"/* スタディブルー - 集中力を高める青ベースの学習テーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #F0F9FF;\n  --theme-text-color: #1E3A8A;\n  --theme-border-color: #93C5FD;\n  --theme-hover-bg-color: #DBEAFE;\n  --theme-accent-color: #3B82F6;\n  --theme-heading-color: #1E40AF;\n  --theme-subtext-color: #3730A3;\n  --theme-muted-text-color: #6366F1;\n  --theme-divider-color: #BFDBFE;\n\n  /* Typography */\n  --theme-font-family: \"Noto Sans\", \"Helvetica Neue\", sans-serif;\n  --theme-font-size: 1rem;\n  --theme-heading-font-size: 1.5rem;\n  --theme-small-font-size: 0.875rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 600;\n  --theme-line-height: 1.7;\n\n  /* Layout */\n  --theme-padding: 1rem;\n  --theme-margin: 0.5rem;\n  --theme-border-radius: 0.5rem;\n  --theme-border-width: 1px;\n  --theme-box-shadow: 0 1px 3px 0 rgba(59, 130, 246, 0.1);\n\n  /* Animations */\n  --theme-transition-duration: 200ms;\n\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  transition: background-color var(--theme-transition-duration);\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n}","version":"1.0","type":"css-based","accessibility":null}', NOW(), NOW(), NULL);
INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('academic', 'アカデミック', '研究・論文執筆に適したアカデミックテーマ', true, true, '{"cssContent":"/* アカデミック - 研究・論文執筆に適したアカデミックテーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #FFFBEB;\n  --theme-text-color: #451A03;\n  --theme-border-color: #FED7AA;\n  --theme-hover-bg-color: #FEF3C7;\n  --theme-accent-color: #D97706;\n  --theme-heading-color: #7C2D12;\n  --theme-subtext-color: #92400E;\n  --theme-muted-text-color: #B45309;\n  --theme-divider-color: #FBBF24;\n\n  /* Typography */\n  --theme-font-family: \"Crimson Pro\", \"Georgia\", serif;\n  --theme-font-size: 1.125rem;\n  --theme-heading-font-size: 1.625rem;\n  --theme-small-font-size: 1rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 600;\n  --theme-line-height: 1.8;\n\n  /* Layout */\n  --theme-padding: 1.5rem;\n  --theme-margin: 1rem;\n  --theme-border-radius: 0.25rem;\n  --theme-border-width: 1px;\n  --theme-box-shadow: 0 1px 2px 0 rgba(217, 119, 6, 0.1);\n\n  /* Animations */\n  --theme-transition-duration: 200ms;\n\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  transition: background-color var(--theme-transition-duration);\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n}","version":"1.0","type":"css-based","accessibility":null}', NOW(), NOW(), NULL);
INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('artist', 'アーティスト', 'クリエイティブな発想を促す紫ベースのテーマ', true, true, '{"cssContent":"/* アーティスト - クリエイティブな発想を促す紫ベースのテーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #FEF7FF;\n  --theme-text-color: #581C87;\n  --theme-border-color: #D8B4FE;\n  --theme-hover-bg-color: #F3E8FF;\n  --theme-accent-color: #A855F7;\n  --theme-heading-color: #7C3AED;\n  --theme-subtext-color: #8B5CF6;\n  --theme-muted-text-color: #A78BFA;\n  --theme-divider-color: #DDD6FE;\n\n  /* Typography */\n  --theme-font-family: \"Playfair Display\", \"Times New Roman\", serif;\n  --theme-font-size: 1.125rem;\n  --theme-heading-font-size: 1.75rem;\n  --theme-small-font-size: 1rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 700;\n  --theme-line-height: 1.6;\n\n  /* Layout */\n  --theme-padding: 1.25rem;\n  --theme-margin: 0.75rem;\n  --theme-border-radius: 0.75rem;\n  --theme-border-width: 2px;\n  --theme-box-shadow: 0 4px 6px -1px rgba(168, 85, 247, 0.1);\n\n  /* Animations */\n  --theme-transition-duration: 300ms;\n\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  transition: background-color var(--theme-transition-duration);\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n}","version":"1.0","type":"css-based","accessibility":null}', NOW(), NOW(), NULL);
INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('vintage', 'ヴィンテージ', 'レトロで温かみのあるヴィンテージテーマ', true, true, '{"cssContent":"/* ヴィンテージ - レトロで温かみのあるヴィンテージテーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #F5F5DC;\n  --theme-text-color: #8B4513;\n  --theme-border-color: #DEB887;\n  --theme-hover-bg-color: #F0E68C;\n  --theme-accent-color: #CD853F;\n  --theme-heading-color: #A0522D;\n  --theme-subtext-color: #D2691E;\n  --theme-muted-text-color: #BC8F8F;\n  --theme-divider-color: #F4A460;\n\n  /* Typography */\n  --theme-font-family: \"EB Garamond\", \"Garamond\", serif;\n  --theme-font-size: 1.125rem;\n  --theme-heading-font-size: 1.625rem;\n  --theme-small-font-size: 1rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 600;\n  --theme-line-height: 1.8;\n\n  /* Layout */\n  --theme-padding: 1.5rem;\n  --theme-margin: 1rem;\n  --theme-border-radius: 0.125rem;\n  --theme-border-width: 1px;\n  --theme-box-shadow: 0 2px 4px 0 rgba(139, 69, 19, 0.1);\n\n  /* Animations */\n  --theme-transition-duration: 250ms;\n\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  transition: background-color var(--theme-transition-duration);\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n}","version":"1.0","type":"css-based","accessibility":null}', NOW(), NOW(), NULL);
INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('sakura-pink', 'サクラピンク', '春の桜をイメージした優雅なピンクテーマ', true, true, '{"cssContent":"/* サクラピンク - 春の桜をイメージした優雅なピンクテーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #FDF2F8;\n  --theme-text-color: #831843;\n  --theme-border-color: #FBCFE8;\n  --theme-hover-bg-color: #FCE7F3;\n  --theme-accent-color: #EC4899;\n  --theme-heading-color: #9D174D;\n  --theme-subtext-color: #BE185D;\n  --theme-muted-text-color: #DB2777;\n  --theme-divider-color: #F9A8D4;\n\n  /* Typography */\n  --theme-font-family: \"Noto Serif JP\", \"Yu Mincho\", serif;\n  --theme-font-size: 1rem;\n  --theme-heading-font-size: 1.5rem;\n  --theme-small-font-size: 0.875rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 500;\n  --theme-line-height: 1.7;\n\n  /* Layout */\n  --theme-padding: 1rem;\n  --theme-margin: 0.5rem;\n  --theme-border-radius: 0.75rem;\n  --theme-border-width: 1px;\n  --theme-box-shadow: 0 1px 3px 0 rgba(236, 72, 153, 0.1);\n\n  /* Animations */\n  --theme-transition-duration: 250ms;\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  transition: background-color var(--theme-transition-duration);\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n}","version":"1.0","type":"css-based","accessibility":null}', NOW(), NOW(), NULL);
INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('ocean-blue', 'オーシャンブルー', '夏の海をイメージした爽やかなブルーテーマ', true, true, '{"cssContent":"/* オーシャンブルー - 夏の海をイメージした爽やかなブルーテーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #F0F9FF;\n  --theme-text-color: #0C4A6E;\n  --theme-border-color: #7DD3FC;\n  --theme-hover-bg-color: #E0F2FE;\n  --theme-accent-color: #0EA5E9;\n  --theme-heading-color: #0369A1;\n  --theme-subtext-color: #0284C7;\n  --theme-muted-text-color: #0EA5E9;\n  --theme-divider-color: #38BDF8;\n\n  /* Typography */\n  --theme-font-family: \"Open Sans\", \"Helvetica Neue\", sans-serif;\n  --theme-font-size: 1rem;\n  --theme-heading-font-size: 1.5rem;\n  --theme-small-font-size: 0.875rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 600;\n  --theme-line-height: 1.6;\n\n  /* Layout */\n  --theme-padding: 1rem;\n  --theme-margin: 0.5rem;\n  --theme-border-radius: 0.5rem;\n  --theme-border-width: 1px;\n  --theme-box-shadow: 0 1px 3px 0 rgba(14, 165, 233, 0.1);\n\n  /* Animations */\n  --theme-transition-duration: 200ms;\n\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  transition: background-color var(--theme-transition-duration);\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n}","version":"1.0","type":"css-based","accessibility":null}', NOW(), NOW(), NULL);
INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('natural-green', 'ナチュラルグリーン', '自然をイメージした癒しの緑テーマ', true, true, '{"cssContent":"/* ナチュラルグリーン - 自然をイメージした癒しの緑テーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #F0FDF4;\n  --theme-text-color: #14532D;\n  --theme-border-color: #BBF7D0;\n  --theme-hover-bg-color: #DCFCE7;\n  --theme-accent-color: #22C55E;\n  --theme-heading-color: #15803D;\n  --theme-subtext-color: #166534;\n  --theme-muted-text-color: #16A34A;\n  --theme-divider-color: #86EFAC;\n\n  /* Typography */\n  --theme-font-family: \"Inter\", system-ui, sans-serif;\n  --theme-font-size: 1rem;\n  --theme-heading-font-size: 1.5rem;\n  --theme-small-font-size: 0.875rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 500;\n  --theme-line-height: 1.7;\n\n  /* Layout */\n  --theme-padding: 1rem;\n  --theme-margin: 0.5rem;\n  --theme-border-radius: 0.5rem;\n  --theme-border-width: 1px;\n  --theme-box-shadow: 0 1px 3px 0 rgba(34, 197, 94, 0.1);\n\n  /* Animations */\n  --theme-transition-duration: 200ms;\n\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  transition: background-color var(--theme-transition-duration);\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n}","version":"1.0","type":"css-based","accessibility":null}', NOW(), NOW(), NULL);
INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('high-contrast', 'ハイコントラスト', '視覚的な識別性を重視したハイコントラストテーマ', true, true, '{"cssContent":"/* ハイコントラスト - 視覚的な識別性を重視したハイコントラストテーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #FFFFFF;\n  --theme-text-color: #000000;\n  --theme-border-color: #000000;\n  --theme-hover-bg-color: #F0F0F0;\n  --theme-accent-color: #FF0000;\n  --theme-heading-color: #000000;\n  --theme-subtext-color: #333333;\n  --theme-muted-text-color: #666666;\n  --theme-divider-color: #000000;\n\n  /* Typography */\n  --theme-font-family: \"Arial\", sans-serif;\n  --theme-font-size: 1.125rem; /* 大きめのフォントサイズ */\n  --theme-heading-font-size: 1.75rem;\n  --theme-small-font-size: 1rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 700;\n  --theme-bold-font-weight: 900;\n  --theme-line-height: 1.8;\n\n  /* Layout */\n  --theme-padding: 1.5rem;\n  --theme-margin: 1rem;\n  --theme-border-radius: 0;\n  --theme-border-width: 2px;\n  --theme-box-shadow: none;\n\n  /* Animations - アクセシビリティのため無効 */\n  --theme-transition-duration: 0ms;\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  /* アニメーション無効 */\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n  border-width: 2px; /* より見やすく */\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n  font-weight: var(--theme-bold-font-weight); /* より読みやすく */\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n  font-weight: var(--theme-bold-font-weight);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n  border-width: 2px;\n}","version":"1.0","type":"css-based","accessibility":{"highContrast":true,"reducedMotion":true,"fontSize":"large"}}', NOW(), NOW(), NULL);
INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('sepia-eye-care', 'セピア護眼', '目の疲れを軽減するセピア調テーマ', true, true, '{"cssContent":"/* セピア護眼 - 目の疲れを軽減するセピア調テーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #F4F1E8;\n  --theme-text-color: #3E2723;\n  --theme-border-color: #D7CCC8;\n  --theme-hover-bg-color: #EFEBE9;\n  --theme-accent-color: #8D6E63;\n  --theme-heading-color: #3E2723;\n  --theme-subtext-color: #5D4037;\n  --theme-muted-text-color: #795548;\n  --theme-divider-color: #BCAAA4;\n\n  /* Typography */\n  --theme-font-family: \"Georgia\", \"Times New Roman\", serif;\n  --theme-font-size: 1.125rem;\n  --theme-heading-font-size: 1.625rem;\n  --theme-small-font-size: 1rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 600;\n  --theme-line-height: 1.8;\n\n  /* Layout */\n  --theme-padding: 1.25rem;\n  --theme-margin: 0.75rem;\n  --theme-border-radius: 0.25rem;\n  --theme-border-width: 1px;\n  --theme-box-shadow: 0 1px 2px 0 rgba(62, 39, 35, 0.1);\n\n  /* Animations */\n  --theme-transition-duration: 100ms;\n\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  transition: background-color var(--theme-transition-duration);\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n}","version":"1.0","type":"css-based","accessibility":{"reducedMotion":true,"fontSize":"medium"}}', NOW(), NOW(), NULL);
INSERT INTO "themes" ("id", "name", "description", "isSystem", "isPublic", "styles", "createdAt", "updatedAt", "created_by_id") VALUES ('warm-beige', 'ウォームベージュ', 'カフェのような温かみのあるベージュテーマ', true, true, '{"cssContent":"/* ウォームベージュ - カフェのような温かみのあるベージュテーマ */\n\n:root {\n  /* Colors */\n  --theme-bg-color: #FEF3E2;\n  --theme-text-color: #78350F;\n  --theme-border-color: #FED7AA;\n  --theme-hover-bg-color: #FEF3C7;\n  --theme-accent-color: #F59E0B;\n  --theme-heading-color: #92400E;\n  --theme-subtext-color: #B45309;\n  --theme-muted-text-color: #D97706;\n  --theme-divider-color: #FBBF24;\n\n  /* Typography */\n  --theme-font-family: \"Source Sans Pro\", \"Helvetica Neue\", sans-serif;\n  --theme-font-size: 1rem;\n  --theme-heading-font-size: 1.5rem;\n  --theme-small-font-size: 0.875rem;\n  --theme-font-weight: 400;\n  --theme-heading-font-weight: 600;\n  --theme-line-height: 1.6;\n\n  /* Layout */\n  --theme-padding: 1rem;\n  --theme-margin: 0.5rem;\n  --theme-border-radius: 0.5rem;\n  --theme-border-width: 1px;\n  --theme-box-shadow: 0 1px 2px 0 rgba(245, 158, 11, 0.1);\n\n  /* Animations */\n  --theme-transition-duration: 200ms;\n\n}\n\n/* メモコンテナ */\n.memo-container {\n  background-color: var(--theme-bg-color);\n  color: var(--theme-text-color);\n  border: var(--theme-border-width) solid var(--theme-border-color);\n  border-radius: var(--theme-border-radius);\n  padding: var(--theme-padding);\n  margin: var(--theme-margin);\n  box-shadow: var(--theme-box-shadow);\n  font-family: var(--theme-font-family);\n  font-size: var(--theme-font-size);\n  line-height: var(--theme-line-height);\n  transition: background-color var(--theme-transition-duration);\n}\n\n.memo-container:hover {\n  background-color: var(--theme-hover-bg-color);\n}\n\n/* 見出し */\n.memo-title, h1, h2, h3, h4, h5, h6 {\n  color: var(--theme-heading-color);\n  font-size: var(--theme-heading-font-size);\n  font-weight: var(--theme-heading-font-weight);\n  font-family: var(--theme-font-family);\n}\n\n/* アクセント要素 */\n.memo-accent, .button-primary, .link-primary {\n  color: var(--theme-accent-color);\n  border-color: var(--theme-accent-color);\n}\n\n/* サブテキスト */\n.memo-subtext, .text-secondary {\n  color: var(--theme-subtext-color);\n  font-size: var(--theme-small-font-size);\n}\n\n/* ミュートテキスト */\n.memo-muted, .text-muted {\n  color: var(--theme-muted-text-color);\n}\n\n/* 区切り線 */\n.memo-divider, .divider, hr {\n  border-color: var(--theme-divider-color);\n}","version":"1.0","type":"css-based","accessibility":null}', NOW(), NOW(), NULL);
